<template>
  <div class="grade-center">
    <header class="grade-header">
      <div><div class="eyebrow">教师工作台 / 统一执行入口</div><h1>批改中心</h1><p>所有需要教师确认的作业和重练任务，都在这里处理。</p></div>
      <el-button plain :loading="loading" @click="loadData"><el-icon><Refresh /></el-icon>刷新</el-button>
    </header>
    <section class="grade-summary" aria-label="批改任务概览">
      <div class="summary-card summary-card--attention"><span>待处理</span><strong>{{ pendingCount }}</strong><small>优先完成</small></div><div class="summary-card"><span>全部任务</span><strong>{{ allTasks.length }}</strong><small>作业与重练</small></div><div class="summary-card"><span>作业任务</span><strong>{{ homeworkCount }}</strong><small>学生上传</small></div><div class="summary-card"><span>重练任务</span><strong>{{ retryCount }}</strong><small>错题验证</small></div>
    </section>
    <section class="task-surface">
      <div class="task-toolbar"><div class="task-toolbar-title"><strong>批改任务</strong><span>{{ visibleTasks.length }} 份</span></div><el-select v-model="studentId" clearable class="student-filter" placeholder="全部学生" @change="syncQuery"><el-option v-for="student in students" :key="student.id" :label="student.name" :value="student.id" /></el-select><div class="source-tabs" role="tablist" aria-label="任务来源"><button v-for="item in sourceTabs" :key="item.key" :class="{ active: sourceFilter === item.key }" @click="sourceFilter = item.key">{{ item.label }}<span>{{ item.count }}</span></button></div><div class="status-tabs" role="tablist" aria-label="任务状态"><button v-for="item in statusTabs" :key="item.key" :class="{ active: statusFilter === item.key }" @click="statusFilter = item.key">{{ item.label }}</button></div></div>
      <div v-if="loading" class="center-state"><el-icon class="is-loading"><Loading /></el-icon><strong>正在加载批改任务</strong><span>正在同步学生作业和重练记录</span></div>
      <div v-else-if="visibleTasks.length" class="task-table"><div class="table-head"><span>任务</span><span>学生</span><span>来源</span><span>题目</span><span>状态</span><span>操作</span></div><article v-for="task in visibleTasks" :key="task.key" class="task-row"><div class="task-name"><strong>{{ task.name }}</strong><small>{{ task.meta }}</small></div><span class="student-name">{{ task.studentName }}</span><span class="source-badge" :class="`source-badge--${task.source}`">{{ task.sourceLabel }}</span><span class="muted">{{ task.questionCount }} 题<span v-if="task.pendingCount"> ? {{ task.pendingCount }} 待处理</span></span><el-tag class="status-tag" :type="task.status === 'completed' ? 'success' : 'warning'" size="small" effect="plain">{{ task.statusLabel }}</el-tag><el-button class="row-action" type="primary" text @click="openTask(task)">{{ task.status === 'completed' ? '查看结果' : '开始批改' }}</el-button></article></div>
      <div v-else class="center-state"><el-icon><Document /></el-icon><strong>暂无待处理任务</strong><span>新上传的作业或生成的重练任务会显示在这里。</span></div>
    </section>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Document, Loading, Refresh } from '@element-plus/icons-vue'
import { getGeneratedExamsByStudent, getStudents, getTasksByStudent } from '../../services/apiService'
const route=useRoute(); const router=useRouter(); const students=ref([]); const allTasks=ref([]); const loading=ref(true); const studentId=ref(route.query.studentId||''); const sourceFilter=ref(route.query.source==='retry'?'retry':'all'); const statusFilter=ref('pending')
const pendingCount=computed(()=>allTasks.value.filter(item=>item.status!=='completed').length); const homeworkCount=computed(()=>allTasks.value.filter(item=>item.source==='homework').length); const retryCount=computed(()=>allTasks.value.filter(item=>item.source==='retry').length); const visibleTasks=computed(()=>allTasks.value.filter(item=>(sourceFilter.value==='all'||item.source===sourceFilter.value)&&(statusFilter.value==='all'||(statusFilter.value==='pending'?item.status!=='completed':item.status==='completed'))))
const sourceTabs=computed(()=>[{key:'all',label:'全部',count:allTasks.value.length},{key:'homework',label:'作业',count:homeworkCount.value},{key:'retry',label:'重练',count:retryCount.value}]); const statusTabs=[{key:'pending',label:'待处理'},{key:'all',label:'全部状态'},{key:'completed',label:'已完成'}]
const date=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?'时间未知':`${d.getMonth()+1}月${d.getDate()}日`}; const homework=(t,s)=>{const done=t.status==='reviewed';const n=Number(t.question_count||t.total_questions||t.total_count||0);return {key:`homework-${s.id}-${t.id}`,id:t.id,studentId:s.id,studentName:s.name,source:'homework',sourceLabel:'学生作业',name:t.original_name||'未命名作业',meta:t.created_at?`上传于 ${date(t.created_at)}`:'学生上传的作业',questionCount:n,pendingCount:done?0:n,status:done?'completed':'pending',statusLabel:done?'已完成':'待批改'}}; const retry=(t,s)=>{const done=t.status==='graded';const n=Number(t.total_count||t.question_ids?.length||0);return {key:`retry-${s.id}-${t.id}`,id:t.id,studentId:s.id,studentName:s.name,source:'retry',sourceLabel:'错题重练',name:t.name||'未命名重练',meta:t.created_at?`创建于 ${date(t.created_at)}`:'来自错题池',questionCount:n,pendingCount:done?0:n,status:done?'completed':'pending',statusLabel:done?'已完成':'待批改'}}
async function loadData(){loading.value=true;try{const r=await getStudents(false);students.value=r.data||r||[];const targets=studentId.value?students.value.filter(s=>String(s.id)===String(studentId.value)):students.value;const lists=await Promise.all(targets.map(async s=>{const [tasks,exams]=await Promise.all([getTasksByStudent(s.id,false).catch(()=>[]),getGeneratedExamsByStudent(s.id,false).catch(()=>[])]);return [...(tasks||[]).map(t=>homework(t,s)),...(exams||[]).map(t=>retry(t,s))]}));allTasks.value=lists.flat().sort((a,b)=>(a.status==='completed'?1:-1)-(b.status==='completed'?1:-1))}finally{loading.value=false}}
function syncQuery(){router.replace({path:'/grade',query:studentId.value?{studentId:studentId.value,...(sourceFilter.value!=='all'?{source:sourceFilter.value}:{})}:sourceFilter.value!=='all'?{source:sourceFilter.value}:{}});loadData()} function openTask(t){router.push({path:'/grade/task',query:{studentId:t.studentId,taskId:t.id,source:t.source}})} onMounted(loadData)
</script>
<style scoped>
