g)}.source-tabs button.active,.status-tabs button.active{color:var(--wb-primary);background:var(--wb-primary-mist);font-weight:600}.source-tabs span{margin-left:5px;color:var(--wb-text-tertiary);font-size:11px}.table-head,.task-row{display:grid;grid-template-columns:minmax(250px,1.5fr) 120px 100px 145px 90px 100px;align-items:center;gap:16px;padding:0 20px}.table-head{min-height:36px;color:var(--wb-text-tertiary);background:var(--wb-bg);font-size:11px}.task-row{min-height:70px;border-bottom:1px solid var(--wb-border-light)}.task-row:last-child{border-bottom:0}.task-row:hover{background:#FAFBFF}.task-name{min-width:0;display:flex;flex-direction:column;gap:5px}.task-name strong{overflow:hidden;color:var(--wb-text);font-size:13px;text-overflow:ellipsis;white-space:nowrap}.task-name small,.student-name,.muted{color:var(--wb-text-secondary);font-size:12px}.source-badge{width:fit-content;padding:3px 7px;border-radius:5px;font-size:11px}.source-badge--homework{color:var(--wb-primary);background:var(--wb-primary-mist)}.source-badge--retry{color:var(--wb-accent);background:var(--wb-accent-soft)}.status-tag{justify-self:start}.row-action{min-width:78px}.center-state{display:flex;align-items:center;justify-content:center;min-height:300px;flex-direction:column;gap:8px;color:var(--wb-text-tertiary);font-size:13px}.center-state strong{color:var(--wb-text);font-size:14px}.center-state .el-icon{font-size:30px}@media(max-width:1000px){.grade-center{padding:24px}.task-toolbar{flex-wrap:wrap}.task-toolbar-title{width:100%}.table-head{display:none}.task-row{grid-template-columns:1fr auto;gap:7px 12px;padding:14px 16px}.task-name{grid-row:span 3}.task-row>.source-badge,.task-row>.status-tag,.task-row>.row-action{justify-self:end}}@media(max-width:600px){.grade-center{padding:20px 16px 32px}.grade-header{align-items:flex-start;flex-direction:column;gap:12px}.grade-summary{grid-template-columns:repeat(2,1fr)}.summary-card:nth-child(2){border-right:0}.summary-card:nth-child(-n+2){border-bottom:1px solid var(--wb-border-light)}.task-toolbar{align-items:stretch;flex-direction:column}.student-filter{width:100%}.source-tabs,.status-tabs{overflow-x:auto}}
</style>
